	public JavaSourceCompiler addSource(Map<String, String> sourceCodeMap) {
<COVER>		if (MapUtil.isNotEmpty(sourceCodeMap)) {
<COVER>			sourceCodeMap.forEach(this::addSource);
		}
<COVER>		return this;
	}

	/**
