	 */
	public JavaSourceCompiler addSource(String className, String sourceCode) {
<COVER>		if (className != null && sourceCode != null) {
<COVER>			this.sourceList.add(new StringResource(sourceCode, className));
		}
<COVER>		return this;
	}

