	public ClassLoader compile() {
<COVER>		return compile(null);
	}

	/**
	 * 编译所有文件并返回类加载器
	 *
	 * @param options 编译参数
	 * @return 类加载器
	 */
	public ClassLoader compile(List<String> options) {
		// 获得classPath
<COVER>		final List<File> classPath = getClassPath();
<COVER>		final URL[] urLs = URLUtil.getURLs(classPath.toArray(new File[0]));
<COVER>		final URLClassLoader ucl = URLClassLoader.newInstance(urLs, this.parentClassLoader);
<COVER>		if (sourceList.isEmpty()) {
			// 没有需要编译的源码文件返回加载zip或jar包的类加载器
			return ucl;
		}

		// 创建编译器
<COVER>		final JavaClassFileManager javaFileManager = new JavaClassFileManager(ucl, CompilerUtil.getFileManager());

		// classpath
<COVER>		if (null == options) {
<COVER>			options = new ArrayList<>();
		}
<COVER>		if (false == classPath.isEmpty()) {
			final List<String> cp = CollUtil.map(classPath, File::getAbsolutePath, true);
			options.add("-cp");
			options.add(CollUtil.join(cp, FileUtil.isWindows() ? ";" : ":"));
		}

		// 编译文件
<COVER>		final DiagnosticCollector<? super JavaFileObject> diagnosticCollector = new DiagnosticCollector<>();
<COVER>		final List<JavaFileObject> javaFileObjectList = getJavaFileObject();
<COVER>		final CompilationTask task = CompilerUtil.getTask(javaFileManager, diagnosticCollector, options, javaFileObjectList);
		try {
<COVER>			if (task.call()) {
				// 加载编译后的类
<COVER>				return javaFileManager.getClassLoader(StandardLocation.CLASS_OUTPUT);
			}
		} finally {
<COVER>			IoUtil.close(javaFileManager);
		}
		//编译失败,收集错误信息
		throw new CompilerException(DiagnosticUtil.getMessages(diagnosticCollector));
