import org.junit.Assert;
import org.junit.Test;

import java.util.*;
import java.util.function.Function;

public class CollStreamUtilTest {

    @Test
    public void testToIdentityMap() {
        // Test with null collection
        Map<Long, Student> map = CollStreamUtil.toIdentityMap(null, Student::getStudentId);
        Assert.assertEquals(Collections.emptyMap(), map);

        // Test with empty collection
        List<Student> list = new ArrayList<>();
        map = CollStreamUtil.toIdentityMap(list, Student::getStudentId);
        Assert.assertEquals(Collections.emptyMap(), map);

        // Test with populated collection
        list.add(new Student(1, 101, 1L, "Alice"));
        list.add(new Student(2, 102, 2L, "Bob"));
        list.add(new Student(3, 103, 3L, "Charlie"));

        map = CollStreamUtil.toIdentityMap(list, Student::getStudentId);
        Assert.assertEquals(3, map.size());
        Assert.assertEquals("Alice", map.get(1L).getName());
        Assert.assertEquals("Bob", map.get(2L).getName());
        Assert.assertEquals("Charlie", map.get(3L).getName());

        // Test with collection containing null values
        list.add(new Student(4, 104, 4L, null));
        map = CollStreamUtil.toIdentityMap(list, Student::getStudentId);
        Assert.assertNull(map.get(4L).getName());
    }

    public static class Student {
        private long termId;
        private long classId;
        private Long studentId;
        private String name;

        public Student(long termId, long classId, Long studentId, String name) {
            this.termId = termId;
            this.classId = classId;
            this.studentId = studentId;
            this.name = name;
        }

        public Long getStudentId() {
            return studentId;
        }

