package cn.hutool.core.collection;

import org.junit.Assert;
import org.junit.Test;
import cn.hutool.core.lang.Opt;
import cn.hutool.core.collection.CollUtil;
import cn.hutool.core.text.CharSequenceUtil;

import java.util.*;
import java.util.function.Function;

public class CollStreamUtilTest {

    @Test
    public void testGroupByKey() {
        // Test with null collection
        Map<Long, List<Student>> map = CollStreamUtil.groupByKey(null, Student::getClassId);
        Assert.assertTrue(CollUtil.isEmpty(map));

        // Test with empty collection
        List<Student> list = new ArrayList<>();
        map = CollStreamUtil.groupByKey(list, Student::getClassId);
        Assert.assertTrue(CollUtil.isEmpty(map));

        // Test with sample data
        list.add(new Student(1, 101, 1001, "Alice"));
        list.add(new Student(1, 102, 1002, "Bob"));
        list.add(new Student(2, 101, 1003, "Charlie"));
        map = CollStreamUtil.groupByKey(list, Student::getClassId);

        // Prepare expected map
        Map<Long, List<Student>> expected = new HashMap<>();
        expected.put(101L, Arrays.asList(list.get(0), list.get(2)));
        expected.put(102L, Collections.singletonList(list.get(1)));

        // Check if map equals expected
        Assert.assertEquals(expected, map);

        // Use Opt.orElse
        List<Student> studentsInClass101 = Opt.ofNullable(map.get(101L)).orElse(Collections.emptyList());
        Assert.assertEquals("Number of students in class 101 should be 2", 2, studentsInClass101.size());

        // Use CharSequenceUtil.format in assertion message
        Assert.assertTrue(CharSequenceUtil.format("Map should contain class ID {}", 103L),
                map.containsKey(101L));
    }

    /**
     * Student class representing a student entity.
     */
    public static class Student {
        private long termId;    // Term ID
        private long classId;   // Class ID
        private long studentId; // Student ID
        private String name;    // Student Name

        public Student(long termId, long classId, long studentId, String name) {
            this.termId = termId;
            this.classId = classId;
            this.studentId = studentId;
            this.name = name;
        }

        public long getTermId() {
            return termId;
        }

        public long getClassId() {
            return classId;
        }

        public long getStudentId() {
            return studentId;
        }

        public String getName() {
            return name;
        }

        // Override equals and hashCode for accurate comparison in assertions
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Student)) return false;
            Student student = (Student) o;
            return termId == student.termId &&
                    classId == student.classId &&
                    studentId == student.studentId &&
                    Objects.equals(name, student.name);
        }

        @Override
        public int hashCode() {
            return Objects.hash(termId, classId, studentId, name);
        }
    }
}

