        Collection<Integer> numbers = CollUtil.newArrayList(1, 2, 3, 4, 5);
        Predicate<Integer> isEven = num -> num % 2 == 0;
        Assert.assertTrue(CollUtil.contains(numbers, isEven));

        // Test with a non-empty collection where the predicate is not satisfied
