	 * @return 抽取后的新列表
	 * @since 5.3.5
	 */
	public static <T, R> List<R> map(Iterable<T> collection, Function<? super T, ? extends R> func, boolean ignoreNull) {
<COVER>		final List<R> fieldValueList = new ArrayList<>();
<COVER>		if (null == collection) {
			return fieldValueList;
		}

		R value;
<COVER>		for (T t : collection) {
<COVER>			if (null == t && ignoreNull) {
				continue;
			}
<COVER>			value = func.apply(t);
<COVER>			if (null == value && ignoreNull) {
				continue;
			}
<COVER>			fieldValueList.add(value);
		}
<COVER>		return fieldValueList;
	}

