	public static <T> void forEach(Enumeration<T> enumeration, Consumer<T> consumer) {
		if (enumeration == null) {
			return;
		}
		int index = 0;
		while (enumeration.hasMoreElements()) {
			consumer.accept(enumeration.nextElement(), index);
			index++;
		}
	}

