import java.util.*;

public class CollUtilTest {

    @Test
    public void fieldValueAsMapTest() {
        // Create a list of test beans
        List<TestBean> list = new ArrayList<>();
        list.add(new TestBean("Alice", Integer.valueOf(30)));
        list.add(new TestBean("Bob", Integer.valueOf(25)));
        list.add(new TestBean("Charlie", Integer.valueOf(35)));

        // Convert the list to a map with 'name' as key and 'age' as value
        Map<String, Integer> map = CollUtil.<String, Integer>fieldValueAsMap(list, "name", "age");

        // Assert the size of the map
        Assert.assertEquals(3, map.size());

        // Assert individual mappings
        Assert.assertEquals(Integer.valueOf(30), map.get("Alice"));
        Assert.assertEquals(Integer.valueOf(25), map.get("Bob"));
        Assert.assertEquals(Integer.valueOf(35), map.get("Charlie"));

        // Use CharUtil.isBlankChar to ensure no keys contain blank characters
        for (String key : map.keySet()) {
            for (char c : key.toCharArray()) {
                Assert.assertFalse("Key contains a blank character: " + c, CharUtil.isBlankChar(c));
            }
        }
    }

    // Supporting TestBean class
    public static class TestBean {
        private String name;
        private Integer age;

        public TestBean(String name, Integer age) {
            this.name = name;
            this.age = age;
        }

        // Getters
        public String getName() {
            return name;
        }

        public Integer getAge() {
            return age;
        }
    }
}

