	/**
	 * 新建一个HashSet
	 *
	 * @param <T>      集合元素类型
	 * @param isSorted 是否有序，有序返回 {@link LinkedHashSet}，否则返回 {@link HashSet}
	 * @param ts       元素数组
	 * @return HashSet对象
	 */
	@SafeVarargs
	public static <T> HashSet<T> set(boolean isSorted, T... ts) {
<COVER>		if (null == ts) {
			return isSorted ? new LinkedHashSet<>() : new HashSet<>();
		}
<COVER>		int initialCapacity = Math.max((int) (ts.length / .75f) + 1, 16);
<COVER>		final HashSet<T> set = isSorted ? new LinkedHashSet<>(initialCapacity) : new HashSet<>(initialCapacity);
<COVER>		Collections.addAll(set, ts);
<COVER>		return set;
	}

