	/**
	 * 映射键值（参考Python的zip()函数），返回Map无序<br>
	 * 例如：<br>
	 * keys = a,b,c,d<br>
	 * values = 1,2,3,4<br>
	 * delimiter = , 则得到的Map是 {a=1, b=2, c=3, d=4}<br>
	 * 如果两个数组长度不同，则只对应最短部分
	 *
	 * @param keys      键列表
	 * @param values    值列表
	 * @param delimiter 分隔符
	 * @return Map
	 */
	public static Map<String, String> zip(String keys, String values, String delimiter) {
		return zip(keys, values, delimiter, false);
	}

	/**
	 * 映射键值（参考Python的zip()函数）<br>
	 * 例如：<br>
	 * keys = [a,b,c,d]<br>
	 * values = [1,2,3,4]<br>
	 * 则得到的Map是 {a=1, b=2, c=3, d=4}<br>
	 * 如果两个数组长度不同，则只对应最短部分
	 *
	 * @param <K>    键类型
	 * @param <V>    值类型
	 * @param keys   键列表
	 * @param values 值列表
	 * @return Map
	 */
	public static <K, V> Map<K, V> zip(Collection<K> keys, Collection<V> values) {
<COVER>		if (isEmpty(keys) || isEmpty(values)) {
			return MapUtil.empty();
		}

<COVER>		int entryCount = Math.min(keys.size(), values.size());
<COVER>		final Map<K, V> map = MapUtil.newHashMap(entryCount);

<COVER>		final Iterator<K> keyIterator = keys.iterator();
<COVER>		final Iterator<V> valueIterator = values.iterator();
<COVER>		while (entryCount > 0) {
<COVER>			map.put(keyIterator.next(), valueIterator.next());
<COVER>			entryCount--;
		}

<COVER>		return map;
	}

