	 */
	public static <T> int indexOf(Collection<T> collection, Matcher<T> matcher) {
<COVER>		if (isNotEmpty(collection)) {
<COVER>			int index = 0;
<COVER>			for (T t : collection) {
<COVER>				if (null == matcher || matcher.match(t)) {
<COVER>					return index;
