	/**
	 * 取最大值
	 *
	 * @param <T>  元素类型
	 * @param coll 集合
	 * @return 最大值
	 * @see Collections#max(Collection)
	 * @since 4.6.5
	 */
	public static <T extends Comparable<? super T>> T max(Collection<T> coll) {
		return isEmpty(coll) ? null : Collections.max(coll);
	}

	/**
	 * 取最小值
	 *
	 * @param <T>  元素类型
	 * @param coll 集合
	 * @return 最小值
	 * @see Collections#min(Collection)
	 * @since 4.6.5
