	 */
	public static <T> void page(List<T> list, int pageSize, Consumer<List<T>> pageListConsumer) {
<COVER>		if (CollUtil.isEmpty(list) || pageSize <= 0) {
<COVER>			return;
		}

<COVER>		final int total = list.size();
<COVER>		final int totalPage = PageUtil.totalPage(total, pageSize);
<COVER>		for (int pageNo = PageUtil.getFirstPageNo(); pageNo < totalPage + PageUtil.getFirstPageNo(); pageNo++) {
			// 获取当前页在列表中对应的起止序号
<COVER>			final int[] startEnd = PageUtil.transToStartEnd(pageNo, pageSize);
<COVER>			if (startEnd[1] > total) {
<COVER>				startEnd[1] = total;
			}

			// 返回数据
<COVER>			pageListConsumer.accept(sub(list, startEnd[0], startEnd[1]));
