	 */
	@SafeVarargs
	public static <T> List<T> list(boolean isLinked, T... values) {
<COVER>		if (ArrayUtil.isEmpty(values)) {
			return list(isLinked);
		}
<COVER>		final List<T> arrayList = isLinked ? new LinkedList<>() : new ArrayList<>(values.length);
<COVER>		Collections.addAll(arrayList, values);
