	 */
	public static <T> T getFirst(Iterable<T> iterable) {
		if (iterable instanceof List) {
			final List<T> list = (List<T>) iterable;
			return CollUtil.isEmpty(list) ? null: list.get(0);
		}

		return getFirst(getIter(iterable));
	}

