	/**
	 * 获得指定范围内的随机数
	 *
	 * @param minInclude 最小数（包含）
	 * @param maxExclude 最大数（不包含）
	 * @return 随机数
	 */
	public static int randomInt(final int minInclude, final int maxExclude) {
<COVER>		return randomInt(minInclude, maxExclude, true, false);
	}

	/**
