	 * @param includeMin 是否包含最小值
	 * @param includeMax 是否包含最大值
	 * @return 随机数
	 */
	public static int randomInt(int min, int max, final boolean includeMin, final boolean includeMax) {
<COVER>		if (!includeMin) {
