	/**
	 * 创建指定长度的随机索引
	 *
	 * @param length 长度
	 * @return 随机索引
	 * @since 5.2.1
	 */
	public static int[] randomInts(final int length) {
		final int[] range = ArrayUtil.range(length);
		for (int i = 0; i < length; i++) {
			final int random = randomInt(i, length);
			ArrayUtil.swap(range, i, random);
		}
		return range;
	}
	// endregion

	// region ----- randomLong

	/**
	 * 获得随机数
	 *
	 * @return 随机数
