	 * @since 5.5.3
	 */
	public static Segment<Integer> toSegment(int pageNo, int pageSize) {
		final int[] startEnd = transToStartEnd(pageNo, pageSize);
		return new DefaultSegment<>(startEnd[0], startEnd[1]);
	}

