			info[1] = "N";
			info[2] = "false";
			return info;
		}
		info[2] = isValidTWCard(idcard) ? "true" : "false";
	} else if (idcard.matches("^[157][0-9]{6}\\(?[0-9A-Z]\\)?$")) { // 澳门
		info[0] = "澳门";
		info[1] = "N";
		info[2] = "true";
